/* Produktdaten — erzeugt aus unseren eigenen Inseraten (Kleinanzeigen-Profil
 * "riegel-interior", abgerufen am 21.11.2026) plus drei Stücken aus unseren
 * eigenen Showroom-Fotos.
 *
 * WICHTIG: Herstellernamen sind überall entfernt — weder in name, sub noch
 * note darf eine Marke stehen. Die Quelle führt sie teils im Titel
 * ("Habufa Torano Wandtisch"); beim Erzeugen werden sie herausgefiltert.
 * Wer die Liste von Hand ergänzt, muss das selbst beachten.
 *
 * price ist der aktuelle Preis in Euro, was der gestrichene Vorher-Preis.
 * price: null heißt "Preis im Markt" — keine erfundene Zahl.
 *
 * url zeigt auf das Inserat, aus dem der Eintrag stammt. Läuft ein Inserat
 * aus, führt der Link ins Leere — die Daten sind eine Momentaufnahme und
 * müssen beim Nachziehen des Sortiments neu erzeugt werden.
 */

export type Product = {
  id: string;
  cat: string;
  name: string;
  sub: string;
  img: string;
  /** null = Preis nicht hinterlegt, Karte zeigt "Preis im Markt" */
  price: string | null;
  /** durchgestrichener Vorher-Preis */
  was?: string;
  /** Hersteller — nur gesetzt, wenn das Inserat ihn nennt */
  brand?: string;
  masse?: string;
  /** Markt, in dem das Stück steht */
  loc?: string;
  /** zusätzlicher Hinweis auf der aufgeklappten Karte */
  note?: string;
  /** Etikett auf dem Bild: Abverkauf, Sonderposten, 2. Wahl … */
  flag?: string;
  /** das Inserat, aus dem dieser Eintrag stammt */
  url?: string;
  /** kurze Eckdaten aus der Anzeigenbeschreibung */
  specs?: { k: string; v: string }[];
  /** nicht am Lager, wird bestellt */
  bestell?: boolean;
};

